void mbc_gopen_wed::predict(const BallCandidates::PatchYUVClassified& patch, double meanBrightnessOffset)
{
	ASSERT(patch.size() == 16);

	for(size_t x=0; x < patch.size(); x++) {
		for(size_t y=0; y < patch.size(); y++) {
			// TODO: check
			// .pixel.y accesses the brightness channel of the pixel
			// subtract the mean brightness calculated on the dataset and the offset from the module parameters
			float value = (static_cast<float>((patch.data[patch.size() * x + y].pixel.y)) / 255.0f) - static_cast<float>(meanBrightnessOffset);
			in_step[y][x][0] = value;
		}
	}

	cnn(in_step);
}

double mbc_gopen_wed::getRadius() const {
	return 1.0f;
}
Vector2d mbc_gopen_wed::getCenter() const {
	return Vector2d(0.5f, 0.5f);
}
double mbc_gopen_wed::getBallConfidence() const {
	// last dense layer has 2 units that are softmax activated
	// [[0], [1]] --> ball
	// [[1], [0]] --> no_ball
	return scores[1];
}

